// サンプルのデータ元: このワークフローの静的データ（Activate 中の実行で保持される）。
// 本番ではスプレッドシートや n8n の Data Table などに差し替える。応答の形はページ定義の key と列に合わせる。
const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.rows)) store.rows = [];
const rows = store.rows;
const month = new Date().toISOString().slice(0, 7);
return [{ json: {
  open: rows.filter((r) => r.status === '未対応').length,
  month: rows.filter((r) => String(r.date).startsWith(month)).length,
  rows: rows.slice(-200).reverse().map((r) => ({ id: r.id, date: r.date, name: r.name, subject: r.subject, status: r.status })),
} }];

// action ごとに分ける（create = フォーム、done = 表の行の「完了」、remind = ボタン）。
// 入力は gateway がページ定義どおりに検証済み（項目名・型・長さ）。値はログに出さない。
const body = $('Webhook 送信').first().json.body;
const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.rows)) store.rows = [];
const input = body.input || {};
if (body.action === 'create') {
  store.rows.push({
    id: 'inq-' + Date.now().toString(36),
    date: new Date().toISOString().slice(0, 10),
    name: String(input.name || ''),
    subject: String(input.subject || ''),
    status: '未対応',
  });
  return [{ json: { ok: true, message: '登録しました' } }];
}
if (body.action === 'done') {
  const row = store.rows.find((r) => r.id === input.rowId);
  if (!row) return [{ json: { ok: false, message: '見つかりません' } }];
  row.status = '対応済み';
  return [{ json: { ok: true, message: '対応済みにしました' } }];
}
if (body.action === 'remind') {
  // 外への送信（Slack・メールなど）はここに足す。ページ定義に confirm を必ず書く（設計書 K10）
  return [{ json: { ok: true, message: '通知は未設定です' } }];
}
return [{ json: { ok: false, message: '未対応の操作です' } }];
